import java.util.*;

class Solution {
    public long waysToPay(int[] tokens, int fare) {
        long[] ways = new long[fare + 1];   // ways[a] = combinations paying exactly a
        ways[0] = 1;                        // pay nothing: one way
        for (int t : tokens) {              // token values outside -> combinations, not orders
            for (int a = t; a <= fare; a++) {
                ways[a] += ways[a - t];
            }
        }
        return ways[fare];
    }
}

