class Solution:
    def waysToPay(self, tokens: List[int], fare: int) -> int:
        ways = [1] + [0] * fare
        for t in tokens:
            for a in range(t, fare + 1):
                ways[a] += ways[a - t]
        return ways[fare]

javascript:
function waysToPay(tokens, fare) {
  const k = tokens.length;
  const dp = Array.from({length: k + 1}, () => new Array(fare + 1).fill(0));
  dp[0][0] = 1;
  for (let i = 1; i <= k; i++) for (let a = 0; a <= fare; a++)
    dp[i][a] = dp[i-1][a] + (a >= tokens[i-1] ? dp[i][a - tokens[i-1]] : 0);
  return dp[k][fare];
}
